const neo4j = require("neo4j-driver");

/**
 * Clauses that can modify the graph. The harness executes text generated by a
 * language model against the real archive, so anything matching this is refused
 * before it reaches the database. Read transactions are a second line of
 * defence; this is the first.
 */
const WRITE_CLAUSE = /\b(CREATE|MERGE|DELETE|DETACH\s+DELETE|SET|REMOVE|DROP|FOREACH|LOAD\s+CSV|CALL\s+\{[^}]*\b(CREATE|MERGE|DELETE|SET|REMOVE)\b)/i;

/** Procedures that can write, escalate, or leak configuration. */
const BANNED_PROC = /\b(apoc\.(?!coll\.|text\.|map\.|convert\.)|dbms\.|db\.index\.|db\.create|db\.awaitIndex)/i;

function isReadOnly(cypher) {
  const stripped = String(cypher)
    .replace(/\/\/[^\n]*/g, " ")
    .replace(/\/\*[\s\S]*?\*\//g, " ")
    .replace(/'(?:[^'\\]|\\.)*'/g, "''")
    .replace(/"(?:[^"\\]|\\.)*"/g, '""');
  if (WRITE_CLAUSE.test(stripped)) return { ok: false, reason: "contains a write clause" };
  if (BANNED_PROC.test(stripped)) return { ok: false, reason: "calls a restricted procedure" };
  return { ok: true };
}

/** Turn driver failures into one clear sentence instead of a stack trace. */
function explainConnError(err, uri) {
  const msg = String(err && err.message ? err.message : err);
  const code = err && err.code ? String(err.code) : "";
  const host = String(uri || "").replace(/^\w+(\+s{1,2}c?)?:\/\//, "").split("/")[0];

  if (/No routing servers available|ServiceUnavailable|Could not perform discovery/i.test(msg + code)) {
    return [
      `Cannot reach the Neo4j instance at ${host}.`,
      "",
      "  Two common causes, and they look almost identical:",
      "",
      "  1. The AuraDB instance is PAUSED. Free instances pause after 3 days idle.",
      "     Resume it at https://console.neo4j.io and wait 1-3 minutes.",
      "",
      "  2. Port 7687 is BLOCKED by the network. Many campus and corporate",
      "     networks drop outbound database ports. Check with:",
      `         nc -vz ${host} 7687        # should connect`,
      `         nc -vz ${host} 443         # control, should also connect`,
      "     If 443 works and 7687 times out, it is a firewall, not the instance."
    ].join("\n");
  }
  if (/AuthenticationRateLimit|Unauthorized|authentication failure/i.test(msg + code)) {
    return `Neo4j rejected the credentials for ${host}. Check ARCHIVE_NEO4J_USERNAME and ARCHIVE_NEO4J_PASSWORD.`;
  }
  if (/ENOTFOUND|getaddrinfo/i.test(msg)) {
    return `DNS cannot resolve ${host}. If the instance is resuming this is normal for a minute or two; otherwise check ARCHIVE_NEO4J_URI.`;
  }
  if (/ETIMEDOUT|timed out|Failed to establish connection/i.test(msg)) {
    return `Connection to ${host} timed out at the network level, which usually means port 7687 is blocked. Try a different network.`;
  }
  return `Neo4j error talking to ${host}: ${msg}`;
}

async function connect({ uri, username, password }) {
  if (!uri || !username || !password) {
    throw new Error(
      "Missing Neo4j credentials.\n" +
      "  The harness reads ARCHIVE_NEO4J_URI / _USERNAME / _PASSWORD.\n" +
      "  By default it loads them from ../backend/.env — set EVAL_ENV_FILE to point elsewhere."
    );
  }
  const driver = neo4j.driver(uri, neo4j.auth.basic(username, password), {
    connectionTimeout: 15000,
    maxTransactionRetryTime: 5000
  });
  try {
    await driver.verifyConnectivity();
  } catch (err) {
    await driver.close().catch(() => {});
    const e = new Error(explainConnError(err, uri));
    e.isConnectionError = true;
    throw e;
  }
  return driver;
}

/** Run one read-only query with a timeout. Never throws; reports in the result. */
async function runRead(driver, cypher, timeoutMs = 20000) {
  const guard = isReadOnly(cypher);
  if (!guard.ok) {
    return { ok: false, blocked: true, error: `refused: ${guard.reason}`, records: [], ms: 0 };
  }
  const session = driver.session({ defaultAccessMode: neo4j.session.READ });
  const started = Date.now();
  try {
    const result = await Promise.race([
      session.executeRead((tx) => tx.run(cypher)),
      new Promise((_, rej) => setTimeout(() => rej(new Error(`query exceeded ${timeoutMs}ms`)), timeoutMs))
    ]);
    return { ok: true, blocked: false, error: "", records: result.records, ms: Date.now() - started };
  } catch (err) {
    return {
      ok: false,
      blocked: false,
      error: String(err && err.message ? err.message : err).split("\n")[0].slice(0, 300),
      records: [],
      ms: Date.now() - started
    };
  } finally {
    await session.close().catch(() => {});
  }
}

async function fetchSchema(driver) {
  const grab = async (proc) => {
    const r = await runRead(driver, `CALL ${proc}`, 10000);
    return r.ok ? r.records.map((x) => x.get(0)) : [];
  };
  return {
    labels: await grab("db.labels()"),
    relationshipTypes: await grab("db.relationshipTypes()"),
    propertyKeys: await grab("db.propertyKeys()")
  };
}

module.exports = { connect, runRead, fetchSchema, isReadOnly, explainConnError };
